 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg for _ in range(w)] for _ in range(h)]
    seen = [[False] * w for _ in range(h)]
    rectangles = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            minr = min(y for y, _ in cells)
            maxr = max(y for y, _ in cells)
            minc = min(x for _, x in cells)
            maxc = max(x for _, x in cells)
            bh, bw = maxr - minr + 1, maxc - minc + 1
            area = bh * bw
            if bh >= 2 and bw >= 2 and area >= 6 and len(cells) / area >= 0.55:
                rectangles.append((color, minr, maxr, minc, maxc))

    for color, minr, maxr, minc, maxc in rectangles:
        for r in range(minr, maxr + 1):
            for c in range(minc, maxc + 1):
                out[r][c] = color
    return out


